import { MenuConfig, MenuItem, MenuFeatureHost } from "../types.js";
/**
 * Adds submenu functionality to the menu component
 * Manages creation, positioning, and interaction with nested submenus
 *
 * @param config - Menu configuration
 * @returns Component enhancer with submenu functionality
 */
declare const withSubmenu: (config: MenuConfig) => <C extends MenuFeatureHost>(component: C) => C & {
    submenu: {
        openSubmenu: (item: MenuItem, index: number, itemElement: HTMLElement) => void;
        closeSubmenu: (level: number) => void;
        closeAllSubmenus: () => void;
        handleSubmenuClick: (item: MenuItem, index: number, itemElement: HTMLElement) => void;
        handleNestedSubmenuClick: (item: MenuItem, index: number, itemElement: HTMLElement) => void;
        handleSubmenuHover: (item: MenuItem, index: number, itemElement: HTMLElement) => void;
        handleSubmenuLeave: () => void;
        hasOpenSubmenu: () => boolean;
        getSubmenuLevel: () => number;
        getActiveSubmenus: () => Array<{
            element: HTMLElement;
            menuItem: HTMLElement;
            level: number;
            isOpening: boolean;
        }>;
    };
};
export default withSubmenu;
